/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    OUTPUT_SCHEMAS, WITHOUT_OUTPUT_SCHEMA, attachOutputSchemas
 * depends    —
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
/**
 * What each tool's answer looks like, as the `outputSchema` a client is sent.
 *
 * A client that receives `structuredContent` can hand a tool's answer to code instead of to a
 * model, but only if it has been told the shape first. These are written from what each tool
 * returns when it is called, not from what its description promises, and
 * `tests/mcp/structured-output.test.ts` calls every read-only tool and holds the answers to them.
 *
 * Three decisions run through all of them:
 *
 * - A schema describes a SUCCESS. A tool that fails answers `{ error, ... }` with `isError`, and
 *   the stdio loop sends that as text alone, with no `structuredContent` -- so a client validating
 *   against one of these never meets an error object it would have to reject.
 * - A "not found" that is an answer rather than a failure (`define_term` with `found: false`) is a
 *   success and must conform. That is why so few fields are required: only the ones present in
 *   every answer the tool gives.
 * - Objects are open. Most tools answer differently by argument -- one chart or the list of
 *   charts -- and a row's columns are the game table's, not this file's. Naming the fields that
 *   are always there is useful; forbidding the rest would fail legitimate answers.
 *
 * A number the game can leave unset, or that a formula can return as NaN, is `number | null`:
 * JSON has no NaN, so it travels as `null` in the structured answer exactly as it does in the text.
 *
 * The tools that run scripts from the development monorepo have no schema here. Their answers are
 * whatever those scripts print, which this package neither owns nor can call to check.
 */

const str = { type: 'string' }
const num = { type: 'number' }
const bool = { type: 'boolean' }
const maybeNum = { type: ['number', 'null'] }
const maybeStr = { type: ['string', 'null'] }
const maybeBool = { type: ['boolean', 'null'] }
const open = { type: 'object' }
const strings = { type: 'array', items: str }
const list = items => ({ type: 'array', items })
const said = (schema, description) => ({ ...schema, description })

/** An open object: the named fields are typed, the required ones always present, others allowed. */
const obj = (properties = {}, required = []) => ({
  type: 'object',
  properties,
  ...(required.length > 0 ? { required } : {}),
})

/** The paging fields every paged tool shares. `next` is the `offset` that continues the list. */
const paging = {
  offset: num,
  returned: num,
  truncated: bool,
  next: said(num, 'The offset that continues the list; absent on the last page.'),
}

const nearest = list(obj({ id: str, label: str, score: maybeNum }))

const oracleEntity = obj({
  id: str,
  label: str,
  kind: str,
  summary: str,
  disambiguation: str,
  units: str,
  claimType: str,
  verification: str,
  traps: strings,
  implementedBy: strings,
  assertions: list(open),
  sources: list(open),
  relations: list(open),
  trapsIncludingNeighbours: list({}),
}, ['id', 'label'])

const contradictions = list(obj({
  subject: str,
  predicate: str,
  claims: list(open),
  likelyValue: {},
  crossSource: bool,
}, ['subject', 'predicate', 'claims']))

