/**
 * Tools that deliberately have no schema: the ones that run a script from the development monorepo.
 *
 * Named rather than left as "whatever is missing above", so that a new tool with no schema is a
 * failing test and a decision, not a silent addition to this list. Their successes still travel
 * as `structuredContent` when they are objects; a client just has nothing to validate them with.
 */
export const WITHOUT_OUTPUT_SCHEMA = new Set([
  'mcp_contract',
  'sdk_kernel_load',
  'sdk_registry_get',
  'sdk_save_graph_get',
  'sdk_planner_compile',
  'sdk_docs_generate',
  'sdk_lsp_diagnostics',
  'sdk_graph_get',
  'sdk_graph_context',
  'sdk_graph_mutate',
  'sdk_graph_validate',
  'sdk_graph_render',
  'trust_coverage_report',
  'trust_drift_check',
  'sdk_debug_snapshot',
  'sdk_debug_validate',
  'sdk_debug_trace',
  'sdk_debug_watch',
])

/**
 * Give each tool in a registry its output schema, in place, leaving any it already declares alone.
 *
 * In place, and called where each registry is defined, so the schema is part of the tool. The
 * development monorepo mounts these registries in a server of its own; a wrapper applied only when
 * this package's server starts would have left that one advertising none.
 */
export function attachOutputSchemas(tools) {
  for (const [name, tool] of Object.entries(tools)) {
    if (!tool.outputSchema && Object.prototype.hasOwnProperty.call(OUTPUT_SCHEMAS, name)) {
      tool.outputSchema = OUTPUT_SCHEMAS[name]
    }
  }
  return tools
}
